48	type Mode = "exact" | "all" | "any";
49	const escapeKql = (text: string) => { return text.replace(/(["\\()])/g, '\\$1'); };
50	const buildKql = (text: string, mode: Mode, fields: any) => {
51	    const cleanedText = text.replace(/[-:;\\/()\[\]{}.,&!?]/g, ' ').replace(/\s+/g, ' ').trim();
52	    const escapedText = escapeKql(cleanedText);
53	    const words = escapedText.split(/\s+/).filter(word => word.length > 0);
54	    if (mode === "exact") {
55	        return fields.map((field: any) => {
56	            const clauses = words.map(word => `${field}:${word}`);
57	            return `(${clauses.join(" AND ")})`;
58	        }).join(" OR ");
59	    }
60	    if (mode === "all") { const perWordClauses = words.map(word => fields.map((field: any) => `${field}:${word}`).join(" OR ")); return perWordClauses.join(" AND "); }
61	    // mode === "any"
62	    const clauses = [];
63	    for (const word of words) { for (const field of fields) { clauses.push(`${field}:${word}`); } }
64	    return clauses.join(" OR ");
65	};
