309	
310	    function getSelectedColumns(advanceSearchData: any) {
311	        const baseFields: any = ["Content", "Filename", "Author", "AuthorOWSUSER", "Editor", "EditorOWSUSER", "Path", "ListName", "ContentType", "SiteName", "Tags"];
312	        const { Title, Description, Other } = advanceSearchData;
313	        if (Title && Description && Other) {
314	            return ["Title", "Description", ...baseFields];
315	        }
316	        const result = [];
317	        if (Title === true) result.push("Title");
318	        if (Description === true) result.push("Description");
319	        if (Other === true) result.push(...baseFields);
320	        return result;
321	    }
322	    const totalPages = 50;
323	    const runSearch = async (sortOption: any, isExactSearch = false, exactTitle = "", silent = false) => {
324	        if (resultType?.current?.length > 0) {
325	            filterDataAfterSearch(silent);
326	            return;
