365	                SortList: [
366	                    {
367	                        Property: getApiSortParam(sortOption),
368	                        Direction: getSortDirection(sortOption)
369	                    }
370	                ],
371	            });
372	            const processedResults = await Promise.all((res.PrimarySearchResults || [])?.map((item: any) => processSearchItem(item, ContextValue)));
373	            if (processedResults != undefined && processedResults?.length > 0) {
374	                processedResults.forEach((TaskData: any) => {
375	                    if (TaskData?.listData != undefined && TaskData?.listData?.Author != undefined) {
376	                        TaskData.listData.Author.autherImage = findUserByName(TaskData?.listData?.Author?.Id)
377	                    }
378	                    if (TaskData?.listData != undefined && TaskData?.listData?.Editor != undefined) {
379	                        TaskData.listData.Editor.autherImage = findUserByName(TaskData?.listData?.Editor?.Id)
380	                    }
381	                })
382	            }
383	            setResults(processedResults);
384	            setCurrentResultsCount(res.PrimarySearchResults?.length || 0);
385	            setCurrentResultsObj(res);
386	            setCurrentPage(1);
387	        } catch (e: any) {
388	            setError(e.message || "Search failed");
389	        } finally {
390	            setLoading(false);
391	        }
392	    };
393	
394	    const runSearchExact = (title: string) => { runSearch(null, true, title); };   // passing exact flag + title
395	    const findUserByName = (name: any) => {
396	        const user = taskUsers.filter((user: any) => user?.AssingedToUser?.Id == name);
397	        if (user[0]?.Item_x0020_Cover)
398	            return user[0].Item_x0020_Cover.Url;
399	        else
400	            return "https://hhhhteams.sharepoint.com/sites/HHHH/PublishingImages/Portraits/icon_user.jpg";
401	    };
402	    const onPageChange = async (page: number) => {
403	        if (!currentResultsObj) return;
404	        setLoading(true);
405	        try {
406	            const res = await currentResultsObj.getPage(page);
407	            const processedResults = await Promise.all((res.PrimarySearchResults || [])?.map((item: any) => processSearchItem(item, ContextValue)));
408	            let filetrResultData: any = [];
409	            if (filtersApplied === true) {
410	                let documentFileType = resultType?.current?.filter((e: any) => e !== 'Task' && e !== 'Portfolio' && e !== 'Project');
411	                let ListType = resultType?.current.filter((e: any) => e === 'Task' || e === 'Portfolio' || e === 'Project');
