type Mode = "exact" | "all" | "any";
const escapeKql = (text: string) => { return text.replace(/(["\\()])/g, '\\$1'); };
const buildKql = (text: string, mode: Mode, fields: any) => {
    const cleanedText = text.replace(/[-:;\\/()\[\]{}.,&!?]/g, ' ').replace(/\s+/g, ' ').trim();
    const escapedText = escapeKql(cleanedText);
    const words = escapedText.split(/\s+/).filter(word => word.length > 0);
    if (mode === "exact") {
        return fields.map((field: any) => {
            const clauses = words.map(word => `${field}:${word}`);
            return `(${clauses.join(" AND ")})`;
        }).join(" OR ");
    }
    if (mode === "all") { const perWordClauses = words.map(word => fields.map((field: any) => `${field}:${word}`).join(" OR ")); return perWordClauses.join(" AND "); }
    // mode === "any"
    const clauses = [];
    for (const word of words) { for (const field of fields) { clauses.push(`${field}:${word}`); } }
    return clauses.join(" OR ");
};
