const findSiteUrl = (url: any) => {
    const urlObj = new URL(url);
    const pathParts = urlObj.pathname.split('/');
    const siteIndex = pathParts.indexOf('sites');
    return urlObj.origin + pathParts.slice(0, siteIndex + 3).join('/');
}
function getSubsiteName(url: any) {
    const urlObj = new URL(url);
    const parts = urlObj.pathname.split('/').filter(Boolean);
    const idx = parts.indexOf('sites');
    if (idx === -1 || parts.length <= idx + 2) return null;
    return parts[idx + 2];
}
