        const startDateISO = moment.utc(startDate).startOf('day').toISOString();
        const endDateISO = moment.utc(endDate).endOf('day').toISOString();
        let filter = `(${body})`;

        let documentFileType = resultType?.current?.filter((e: any) => e !== 'Task' && e !== 'Portfolio' && e !== 'Project');
        let ListType = resultType?.current.filter((e: any) => e === 'Task' || e === 'Portfolio' || e === 'Project');

        // Build Rank filter
        let rankFilter = "";
        if (Array.isArray(smartFilterData?.rank) && smartFilterData.rank.length > 0) {
            rankFilter = `(${smartFilterData.rank.map((r: any) => `ItemRankOWSNMBR:${r}`).join(' OR ')})`;
        }

        const buildUserAndDateFilter = (smartFilterData: any, startDateISO: any, endDateISO: any, dateTypes: any) => {
            const filters = [];
            const teamMember = smartFilterData?.teamMember?.reduce((acc: any, item: any) => [...acc, ...item.checkedObj], []);
            if (teamMember?.length > 0) {
                const createdBy = smartFilterData.isCreatedBy ? teamMember.map((m: any) => `AuthorOWSUSER:"${m.Title}"`).join(' OR ') : null;
                const modifiedBy = smartFilterData.isModifiedby ? teamMember.map((m: any) => `EditorOWSUSER:${m.Email}`).join(' OR ') : null;
                if (createdBy && modifiedBy) {
                    filters.push(`(${createdBy}) OR (${modifiedBy})`);
                } else if (createdBy) {
                    filters.push(`(${createdBy})`);
                } else if (modifiedBy) { filters.push(`(${modifiedBy})`); }
            }
            const dateFilters = [];
            if (dateTypes?.createdDate && startDateISO && endDateISO) { dateFilters.push(`(Created>=${startDateISO} AND Created<=${endDateISO})`); }
            if (dateTypes?.modifiedDate && startDateISO && endDateISO) { dateFilters.push(`(LastModifiedTime>=${startDateISO} AND LastModifiedTime<=${endDateISO})`); }
            if (dateFilters.length > 0) { filters.push(`(${dateFilters.join(' OR ')})`); }
            if (activeSitesSelectedItems?.length > 0) {
                const siteFilter = `(${activeSitesSelectedItems?.map((list: any) => `ListId:"${list?.taskListId}"`).join(' OR ')})`;
                filters.push(`(${siteFilter})`);
            }
            return filters.length > 0 ? filters.join(' AND ') : '';
        };

        if (ListType?.length > 0 || activeSitesSelectedItems?.length > 0) {
            let statusFilter = "";
            let numericPriorityFilter = "";
            const statusPriority = smartFilterData?.statusPriority || [];
            const statusEntry = statusPriority.find((e: any) => e.Title === "Status" && Array.isArray(e.checkedObj) && e.checkedObj.length > 0);
            if (statusEntry) {
                const statusConditions: string[] = [];
                statusEntry.checkedObj.forEach((s: any) => {
                    const title = s?.Title || "";
                    const percentMatch = title.match(/(\d+)\s*%/);
                    if (percentMatch) {
                        const val = Number((parseInt(percentMatch[1], 10) / 100).toFixed(2));
                        statusConditions.push(`PercentCompleteOWSNMBR:${val}`);
                    } else if (title.includes("Preparation") || title.includes("0-9")) {
                        statusConditions.push(`(PercentCompleteOWSNMBR>=0 AND PercentCompleteOWSNMBR<=0.09)`);
                    } else if (title.includes("Ongoing") || title.includes("10-89")) {
                        statusConditions.push(`(PercentCompleteOWSNMBR>=0.10 AND PercentCompleteOWSNMBR<=0.89)`);
                    } else if (title.includes("Completed") || title.includes("90-100")) {
                        statusConditions.push(`(PercentCompleteOWSNMBR>=0.90 AND PercentCompleteOWSNMBR<=1.00)`);
                    } else {
                        const numMatch = title.match(/\b(\d+)\b/);
                        if (numMatch) {
                            const val = Number((parseInt(numMatch[1], 10) / 100).toFixed(2));
                            statusConditions.push(`PercentCompleteOWSNMBR:${val}`);
                        }
                    }
                });
                if (statusConditions.length > 0) {
                    statusFilter = `(${statusConditions.join(' OR ')})`;
                }
            }
            // Build numeric priority filter
            const priorityEntry = statusPriority.find((e: any) => e.Title === "Priority" && Array.isArray(e.checkedObj) && e.checkedObj.length > 0);
            if (priorityEntry) {
                const priorityValues: string[] = [];
                priorityEntry.checkedObj.forEach((obj: any) => {
                    const title = obj?.Title || "";
                    const numMatch = title.match(/\d+/);
                    if (numMatch) {
                        priorityValues.push(numMatch[0]);
                    }
                });
                if (priorityValues.length > 0) {
                    numericPriorityFilter = `(${priorityValues.map((v: string) => `PriorityRankOWSNMBR:${v}`).join(' OR ')})`;
                }
            }
            // Helper to build file type filter if exists
            const buildFileTypeFilter = () => {
                if (documentFileType?.length > 0 && resultType?.current?.length > 0) {
                    return `(${resultType?.current.map((type: any) => `FileType:${type}`).join(' OR ')})`;
                }
                return '';
            };
            // Compose filters for documents and tasks parts
            const docFilterBase = `(contentclass:STS_ListItem_DocumentLibrary AND IsDocument:"true")`;
            const taskFilterBase = `(contentclass:STS_ListItem_Task)`;
            const fileTypeFilter = buildFileTypeFilter();

            // Construct the final filter
            const hasStatus = statusFilter.length > 0;
            const hasPriority = numericPriorityFilter.length > 0;

            const baseBody = `(${body})`;

            let docPart = '';
            let taskPart = '';
            let teamAndDate = buildUserAndDateFilter(smartFilterData, startDateISO, endDateISO, dateTypes)
            if (teamAndDate) {
                teamAndDate = `AND ${teamAndDate}`
            }
            // Document part filter
            if (resultTypeAllDoc === true && documentFileType?.length === 0) {
                docPart = `${baseBody} AND ${docFilterBase} ${teamAndDate}`;
            } else if (documentFileType?.length > 0 && resultTypeAllDoc === false) {
                docPart = `${baseBody} AND ${fileTypeFilter} AND ${docFilterBase} ${teamAndDate}`;
            } else if (resultTypeAllDoc === false && documentFileType?.length === 0) {
                docPart = '';  // No documents returned for this condition
            }
            if (docPart && rankFilter) {
                docPart = `${docPart} AND ${rankFilter}`;
            }
            // Task part filter based on status and/or priority
            if (hasStatus && hasPriority) {
                taskPart = `${baseBody} AND ${statusFilter} AND ${numericPriorityFilter} AND ${taskFilterBase} ${teamAndDate}`;
            } else if (hasStatus && !hasPriority) {
                taskPart = `${baseBody} AND ${statusFilter} AND ${taskFilterBase} ${teamAndDate}`;
            } else if (!hasStatus && hasPriority) {
                taskPart = `${baseBody} AND ${numericPriorityFilter} AND ${taskFilterBase} ${teamAndDate}`;
            } else if (!hasStatus && !hasPriority && (ListType.length > 0 || activeSitesSelectedItems?.length > 0)) {
                taskPart = `${baseBody} AND ${taskFilterBase} ${teamAndDate}`;
            }

            if (docPart && taskPart) {
                filter = `(${docPart}) OR (${taskPart})`;
            } else if (docPart) {
                filter = docPart;
            } else if (taskPart) {
                filter = taskPart;
            }
        } else {
            let teamAndDate = buildUserAndDateFilter(smartFilterData, startDateISO, endDateISO, dateTypes)
            if (teamAndDate) {
                teamAndDate = `AND ${teamAndDate}`
            }
            if (resultTypeAllDoc === true && documentFileType?.length === 0) {
                filter += ` AND (contentclass:STS_ListItem_DocumentLibrary AND IsDocument:"true") ${teamAndDate}`;
            } else if (documentFileType?.length > 0 && resultTypeAllDoc === false) {
                const fileTypeFilter = '(' + resultType?.current.map((type: any) => `FileType:${type}`).join(' OR ') + ')';
                filter += ` AND ${fileTypeFilter} AND (contentclass:STS_ListItem_DocumentLibrary AND IsDocument:"true") ${teamAndDate}`;
            } else if (resultTypeAllDoc === false && documentFileType?.length === 0) {
                filter += ` AND (contentclass:STS_ListItem_DocumentLibrary AND IsDocument:"true") ${teamAndDate}`;
            }
            if (rankFilter) {
                filter += ` AND ${rankFilter}`;
            }
        }
        try {
            const res: any = await sp.search({
                Querytext: filter,
                RowLimit: totalPages,
                StartRow: 0,
                TrimDuplicates: false,
                SelectProperties: ["Title", "Path", "OriginalPath", "HitHighlightedSummary", "FileType", "Filename", "ListItemId", "IsDocument", "ListId", "ListName", "Created", "AuthorOWSUSER", "EditorOWSUSER", "LastModifiedTime", "ItemRankOWSNMBR"],
                Refiners: "FileType",
                EnableQueryRules: true,
                SortList: [
                    {
                        Property: getApiSortParam(sortBy),
                        Direction: getSortDirection(sortBy)
                    }
                ],
            });
            const processedResults = await Promise.all((res.PrimarySearchResults || [])?.map((item: any) => processSearchItem(item, ContextValue)));
            let filetrResultData: any = [];
            let documentFileType = resultType?.current?.filter((e: any) => e !== 'Task' && e !== 'Portfolio' && e !== 'Project');
            let ListType = resultType?.current.filter((e: any) => e === 'Task' || e === 'Portfolio' || e === 'Project');
            if ((resultTypeAllDoc === true && documentFileType?.length === 0) && (ListType?.length > 0)) {
                let docTypeData = processedResults?.filter((data: any) => data?.dataType && data?.dataType == 'Document');
                let resTypeData = processedResults?.filter((data: any) => data?.dataType && ListType?.some((e: any) => (data?.dataType == e)));
                filetrResultData = [...docTypeData, ...resTypeData];
            } else if ((resultTypeAllDoc === true && documentFileType?.length === 0) && ListType?.length == 0) {
                let docTypeData = processedResults?.filter((data: any) => data?.dataType && data?.dataType == 'Document');
                filetrResultData = [...docTypeData];
            } else if ((documentFileType?.length > 0 && resultTypeAllDoc === false) && (ListType?.length > 0)) {
                let docTypeData = processedResults?.filter((data: any) => data?.FileType && documentFileType?.some((e: any) => (data?.FileType == e)));
                let resTypeData = processedResults?.filter((data: any) => data?.dataType && ListType?.some((e: any) => (data?.dataType == e)));
                filetrResultData = [...docTypeData, ...resTypeData];
            } else if ((documentFileType?.length > 0 && resultTypeAllDoc === false) && ListType?.length == 0) {
                let docTypeData = processedResults?.filter((data: any) => data?.FileType && documentFileType?.some((e: any) => (data?.FileType == e)));
                filetrResultData = [...docTypeData];
            } else if ((documentFileType?.length === 0 && ListType?.length > 0)) {
                let resTypeData = processedResults?.filter((data: any) => data?.dataType && ListType?.some((e: any) => (data?.dataType == e)));
                filetrResultData = [...resTypeData];
            } else if ((documentFileType?.length === 0 && ListType?.length === 0)) {
                filetrResultData = processedResults;
            }
            if (filetrResultData != undefined && filetrResultData?.length > 0) {
                filetrResultData.forEach((TaskData: any) => {
                    if (TaskData?.listData != undefined && TaskData?.listData.Author != undefined) {
                        TaskData.listData.Author.autherImage = findUserByName(TaskData?.listData?.Author?.Id)
