    type MenuAction = 'openInBrowser' | 'openInApp' | 'download' | 'openFileLocation' | 'share' | 'copyLink' | 'whoCanSee' | 'DeleteDocumentAndTaskListItem';
    const ACTION_HANDLERS: Record<MenuAction, (res: any) => void> = {
        openInBrowser: res => window.open(`${res?.OriginalPath + "?web=1"}`, '_blank'),
        openInApp: res => {
            if (res?.IsDocument === 'true' && res?.OriginalPath && res?.FileType === 'docx') {
                window.open(`ms-word:ofe|u|${res?.OriginalPath}`, '_blank');
            } else if (res?.IsDocument === 'true' && res?.OriginalPath && res?.FileType === 'xlsx') {
                window.open(`ms-excel:ofe|u|${res?.OriginalPath}`, '_blank');
            } else if (res?.IsDocument === 'true' && res?.OriginalPath && res?.FileType === 'pptx') {
                window.open(`ms-powerpoint:ofe|u|${res?.OriginalPath}`, '_blank');
            }
        },
        download: res => {
            if (res?.OriginalPath) {
                const link = document.createElement('a');
                link.href = res?.OriginalPath;
                link.download = res?.Filename || 'download';
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        },
        openFileLocation: res => {
            if (res?.OriginalPath) {
                let filePath = res?.OriginalPath?.match(/^(.*)[\/\\]/);
                let fileLocation = filePath ? filePath[1] : "";
                window.open(`${fileLocation}`, '_blank');
