                globalCommon.copyPathClipboard(`${res?.coustomOriginalPath ? res?.coustomOriginalPath : res.OriginalPath + "?web=1"}`, dispatchToast, { message: "Copied to clipboard" }, { faildMessage: "Failed to copy" })
            } catch (error) {
            }
