        whoCanSee: res => openShareDialog(res, 'manageAccess'),
        DeleteDocumentAndTaskListItem: async (res: any) => {
            const url = new URL(res?.OriginalPath);
            const pathParts = url.pathname.split('/');
            const siteIndex = pathParts.indexOf('sites');
            const siteUrl = url.origin + pathParts.slice(0, siteIndex + 3).join('/');
            const listId = res.ListId;
            const itemId = res.ListItemId;
            let confirmDelete = await DynamicAlert("DeletetheItem")
            if (confirmDelete) {
                let web = new Web(siteUrl);
                await web.lists.getById(listId).items.getById(itemId).recycle().then((i) => {
                    console.log("Item deleted successfully", i);
                    if (filtersApplied === true) {
                        filterDataAfterSearch();
                    } else {
                        runSearch(sortBy);
                    }
                });
            }
        },
    };
    const handleMenuAction = (action: MenuAction, result: any) => {
        setOpenDropdownId(null);
        const handler = ACTION_HANDLERS[action];
        if (handler) handler(result);
    };



    const editDynamicPopup = (item: any) => {
        const url = new URL(item?.OriginalPath);
        const pathParts = url.pathname.split('/');
        const siteIndex = pathParts.indexOf('sites');
        let siteUrl: any = url.origin + pathParts.slice(0, siteIndex + 3).join('/');
        if (siteUrl) {
            const filteredSites = masterTasksSiteData?.find((site: any) => site?.siteUrl?.includes(siteUrl));
            if (filteredSites) { AllListId = { MasterTaskListID: filteredSites.MasterTaskListID, TaskUserListID: filteredSites.TaskUserListID, SmartMetadataListID: filteredSites.SmartMetadataListID, TaskTimeSheetListID: filteredSites.TaskTimeSheetListID, PortFolioTypeID: filteredSites.PortFolioTypeID, siteUrl: filteredSites?.siteUrl, Context: spfxContext, TaskTypeID: filteredSites.TaskTypeID, isShowTimeEntry: true, }; }
        }
        switch (item?.dataType) {
            case 'Task':
                setIsTask(true);
                setSelectedItems(prev => ({ ...prev, tasks: { ...prev.tasks, ...item?.listData } }));
                break;
            case 'Document':
                if (item?.IsDocument === 'true') {
                    item.FileLeafRef = url.pathname;
                    item.Id = item.ListItemId;
                    item.ID = item.ListItemId;
                    item.FileDirRef = item.FileLeafRef.substring(0, item.FileLeafRef.lastIndexOf('/'));
                    AllListId.DocumentsListID = item?.ListId;
                }
                setIsDocument(true);
                setselectedDocument(item)
                break;
            case 'Portfolio':
                setIsPortfolio(true);
                setSelectedItems(prev => ({ ...prev, portfolios: { ...prev.portfolios, ...item?.listData } }));
                break;
            case 'Project':
                setIsProject(true);
                setSelectedItems(prev => ({ ...prev, projects: { ...prev.projects, ...item?.listData } }));
                break;
            default: break;
        }
    };
    const closeDynamicPopup = (event: any) => {
        if (event === "Close") {
            setIsTask(false);
            setIsDocument(false);
            setIsPortfolio(false);
            setIsProject(false);
        } else if (event === undefined || event === null || event === "") {
            setIsTask(false);
            setIsDocument(false);
            setIsPortfolio(false);
            setIsProject(false);
        } else {
            setIsTask(false);
            setIsDocument(false);
            setIsPortfolio(false);
            setIsProject(false);
            if (filtersApplied === true) {
                filterDataAfterSearch(true);
            } else {
                runSearch(sortBy, false, "", true);
            }
        }
        setselectedDocument({});
        setSelectedItems({ tasks: {}, documents: {}, portfolios: {}, projects: {} });
    };

    const EditDataTimeEntryData = (item: any) => {
        setIsTimeEntry(true);
        setCmsTimeComponent(item);
    };
    const TimeEntryCallBack = React.useCallback((item1) => {
        setIsTimeEntry(false);
        setCmsTimeComponent({});
        setIsSetWorkingTodayTaskPopup(false);
        seteditTimeData({});
    }, []);
    const CreateTimeEntryCallBack = React.useCallback((item1) => {
        setIsTimeEntry(false);
        setCmsTimeComponent({});
        setIsSetWorkingTodayTaskPopup(false);
        seteditTimeData({});
        if (item1 == 'save' && SelectedProp?.OOTBCallback != undefined && typeof SelectedProp?.OOTBCallback == 'function' && SelectedProp?.OOTBCallback.toString().trim() !== '() => {}') {
            SelectedProp.OOTBCallback();
        }
    }, []);

    const handleTimeEntryUpdate = (updatedData: any) => {
        // Handle the updated data from TimeEntryComponent2
        console.log('Updated time entry data:', updatedData);
        seteditTimeData({});
        setIsSetWorkingTodayTaskPopup(false);
        setCmsTimeComponent({});
        // Trigger callback if available
        if (SelectedProp?.OOTBCallback != undefined && typeof SelectedProp?.OOTBCallback == 'function' && SelectedProp?.OOTBCallback.toString().trim() !== '() => {}') {
            SelectedProp.OOTBCallback();
        }
    };

    const onRenderHeader = () => {
        // Check if we're in edit mode by checking if editTimeData has content
        const isEditMode = editTimeData && Object.keys(editTimeData).length > 0 && editTimeData.TaskDate;
        return (
            <div className="flex w-full min-h-8 items-center justify-between gap-3">
                <span className="min-w-0 flex-1 truncate text-left text-[21px] font-semibold leading-8 text-[var(--SiteColor)]">
                    {isEditMode ? "Edit Time Entry" : "Time Entry"}
                </span>
            </div>
        );
    };



    const dropdownRef = React.useRef<HTMLDivElement | null>(null);
    React.useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
                setOpenDropdownId(null);
            }
        };

    }, [openDropdownId]);
    const rerender = React.useReducer(() => ({}), {})[1]
    React.useEffect(() => {
        const params = new URLSearchParams(window.location.search);
        let qValue = params.get('q');
        let kValue = params.get('k');
        if (qValue || kValue) {
            setQuery(qValue);
            queryString.current = qValue || kValue;
        }
        rerender();
    }, []);
    const spOotbResultPage = () => {
        if (query) {
            return `https://hhhhteams.sharepoint.com/sites/HHHH/Sitepages/results.aspx?q=${query}&k=${query}`;
        }
        return `https://hhhhteams.sharepoint.com/sites/HHHH/Sitepages/results.aspx`;
    }
    const toHoursAndMinutes = (totalMinutes: any) => {
        if (!totalMinutes) {
            return 0;
        }
        const hours = Math.floor(totalMinutes / 60);
        const minutes = totalMinutes % 60;
        return `${hours}.${minutes}`;
    };
    const handleCheckboxChange = (e: any) => {
        const DocumentType = [...allFileTypeRefiners]
        const { checked, nextSibling } = e.target;
        const label = nextSibling.innerText.trim();
        if (label === "Documents") {
            if (checked) {
                // add "Documents" and all document types
                setSelectedDirectFilterQuery((prev: any) => {
                    const docs = DocumentType?.map(d => d.RefinementValue);
                    const combined = ["Documents", ...docs, ...prev];
                    return combined.reduce((acc, curr) => {
                        if (!acc.includes(curr)) acc.push(curr);
                        return acc;
                    }, []);
                });
            } else {
                // remove "Documents" and all document types
                setSelectedDirectFilterQuery((prev: any) => prev.filter((item: any) => item !== "Documents" && !DocumentType?.some(d => d.RefinementValue === item)));
            }
        } else if (label === "TASK (AWT)") {
            if (checked) {
                setSelectedDirectFilterQuery((prev: any) => [...prev, "Task"]);
            } else {
                setSelectedDirectFilterQuery((prev: any) => prev.filter((item: any) => item !== "Task"));
            }
        } else if (label === "PROJECT (PXC)") {
            if (checked) {
                setSelectedDirectFilterQuery((prev: any) => [...prev, "Project"]);
            } else {
                setSelectedDirectFilterQuery((prev: any) => prev.filter((item: any) => item !== "Project"));
            }
        } else if (label === "PORTFOLIO (CSF)") {
            if (checked) {
                setSelectedDirectFilterQuery((prev: any) => [...prev, "Portfolio"]);
            } else {
                setSelectedDirectFilterQuery((prev: any) => prev.filter((item: any) => item !== "Portfolio"));
            }
        }
        resultType.current = selectedDirectFilterQuery;
    };

    React.useEffect(() => {
        if (selectedDirectFilterQuery?.length > 0) {
            resultType.current = selectedDirectFilterQuery;
            filterDataAfterSearch();
        } else {
            runSearch(sortBy);
        }
    }, [selectedDirectFilterQuery]);
    const advanceSearchQuery = () => {
        setIsAdvanceSearchPopup(true);
    }

    const setWorkingTodayTaskPopup = (item: any, isEditMode?: boolean, editTimeEntryData?: any) => {
        let WorkingDate = moment().format('DD/MM/YYYY');
        CurrentUserInfo.workingDateUser = WorkingDate;
        if (SelectedProp?.SelectedDate != undefined && SelectedProp?.SelectedDate != '') {
            CurrentUserInfo.workingDateUser = SelectedProp?.SelectedDate;
        }
        setCmsTimeComponent(item);

        // Only set edit data when explicitly in edit mode (pencil icon click)
        // For drag/drop and WT button clicks, always open as fresh entry
        if (isEditMode === true && editTimeEntryData) {
            // If editTimeEntryData is provided directly, use it
            seteditTimeData(editTimeEntryData);
        } else if (isEditMode === true && item?.TodayTaskTimeEntry) {
            // Otherwise, try to find it from task's TodayTaskTimeEntry
            let loggedInUserTime: any = item?.TodayTaskTimeEntry?.filter((timeEntry: any) => timeEntry.AuthorId == CurrentUserInfo?.AssingedToUserId)
            if (loggedInUserTime?.length == 1) {
                var dateValues = loggedInUserTime[0]?.TaskDate?.split("/");
                var dp = dateValues[1] + "/" + dateValues[0] + "/" + dateValues[2];
                var NewDate = new Date(dp);
                loggedInUserTime[0].sortTaskDate = NewDate;
                loggedInUserTime[0].TaskDates = moment(NewDate).format("ddd, DD/MM/YYYY");
                seteditTimeData(loggedInUserTime[0])
            }

