55	function useSearchKey(): string {
56	  const [searchKey, setSearchKey] = React.useState(() => window.location.search || '');
57	
58	  React.useEffect(() => {
59	    const onChange = (): void => {
60	      setSearchKey(window.location.search || '');
61	    };
62	    window.addEventListener('popstate', onChange);
63	    window.addEventListener('hashchange', onChange);
64	    window.addEventListener('spa-search-change', onChange);
65	    return () => {
66	      window.removeEventListener('popstate', onChange);
67	      window.removeEventListener('hashchange', onChange);
68	      window.removeEventListener('spa-search-change', onChange);
69	    };
70	  }, []);
71	
72	  return searchKey;
73	}
