75	/**
76	 * UAT-style outlet: landing tools stay mounted (hide/show).
77	 * Detail profiles remount when query params change so legacy search readers work.
78	 */
79	function FeatureOutlet(props: { pageProps: any }): React.ReactElement {
80	  const { pageProps } = props;
81	
82	  // Prefetch profile chunks while landing tools are open so the first
83	  // Team-Portfolio → Profile click does not flash Suspense PageSkeleton.
84	  React.useEffect(() => {
85	    void import('../features/portfolioProfile/PortfolioProfileFeature');
86	    void import('../features/taskProfile/TaskProfileFeature');
87	    void import('../features/pxcProfile/PxcProfileFeature');
88	  }, []);
89	  const location = useLocation();
90	  const history = useHistory();
91	  const searchKey = useSearchKey();
92	  const pathname = location.pathname || '';
93	
94	  // Keep last profile remount key so clearing ?taskId on leave does not remount with nulls
95	  const portfolioKeyRef = React.useRef('portfolio-profile');
96	  const taskKeyRef = React.useRef('task-profile');
97	  const pxcKeyRef = React.useRef('pxc-profile');
98	
99	  React.useEffect(() => {
100	    if (pathname === '/' || pathname === '') {
101	      history.replace('/team-portfolio');
102	    }
103	  }, [pathname, history]);
104	
105	  const isTeamPortfolio = pathname.indexOf('/team-portfolio') === 0;
106	  const isProjectOverview = pathname.indexOf('/project-overview') === 0;
107	  const isCreateTask = pathname.indexOf('/create-task') === 0;
108	  const isPortfolioProfile = pathname.indexOf('/portfolio-profile') === 0;
109	  const isTaskProfile = pathname.indexOf('/task-profile') === 0;
110	  const isPxcProfile = pathname.indexOf('/pxc-profile') === 0;
