123	   * (`C246-…`, `PX123-…`), and keep-alive leaves those pages mounted, so the
124	   * tab title stuck after leaving for Create Task / OMT. Restore list titles
125	   * here; leave profile routes to the item loaders so PXC/portfolio/task titles
126	   * stay `{ID}-{Title}`.
127	   */
128	  React.useEffect(() => {
129	    if (isCreateTask) {
130	      document.title = 'Create Task';
131	      return;
132	    }
133	    if (isOmt) {
134	      document.title = 'OMT';
135	      return;
136	    }
137	    if (isTeamPortfolio) {
138	      document.title = 'Team Portfolio';
139	      return;
140	    }
141	    if (isProjectOverview) {
142	      document.title = 'PXC Management Overview';
143	    }
144	  }, [isCreateTask, isOmt, isTeamPortfolio, isProjectOverview]);
145	
146	  /**
147	   * Team Portfolio (and profiles) write Portfolio Type color onto document
148	   * `--SiteColor`. Keep-alive leaves that value in place, so Project Overview /
149	   * Create Task / OMT incorrectly stayed Service-green. Restore the default
150	   * site blue for those non-portfolio tabs only — Tailwind `var(--SiteColor)`
151	   * consumers pick it up with no business-logic changes.
152	   */
153	  React.useEffect(() => {
154	    if (isProjectOverview || isCreateTask || isOmt) {
155	      document.documentElement.style.setProperty('--SiteColor', '#2F5596');
156	    }
157	  }, [isProjectOverview, isCreateTask, isOmt]);
158	
159	  /**
160	   * Item ids are mirrored into window.location.search by navigateSpa (legacy
161	   * readers). HashRouter's location.search is often empty while the real URL
162	   * is `workbench.aspx?ProjectId=12920#/pxc-profile`. Prefer window search so
163	   * each profile item gets its own cancellable scope — otherwise every PXC
164	   * shares `pxc-profile`, setActiveScope no-ops, and Documents batches stack.
165	   */
166	  const hashQuery = React.useMemo(() => {
167	    if (searchKey && searchKey.length > 1) {
168	      return searchKey;
169	    }
170	    if (location.search && location.search.length > 1) {
171	      return location.search;
172	    }
173	    if (window.location.hash.indexOf('?') !== -1) {
174	      return window.location.hash.slice(window.location.hash.indexOf('?'));
175	    }
176	    return '';
177	  }, [location.search, location.pathname, searchKey]);
178	
179	  // Publish the active route to the request layer. Leaving a profile aborts
180	  // every SharePoint call it still had in flight (see requestScope).
181	  const scopeId = React.useMemo(() => {
182	    if (isTeamPortfolio) return 'team-portfolio';
183	    if (isProjectOverview) return 'project-overview';
184	    if (isCreateTask) return 'create-task';
185	    if (isOmt) return 'omt';
186	    if (isPortfolioProfile) return `portfolio-profile${hashQuery}`;
187	    if (isTaskProfile) return `task-profile${hashQuery}`;
188	    if (isPxcProfile) return `pxc-profile${hashQuery}`;
189	    return 'global';
190	  }, [
191	    isTeamPortfolio, isProjectOverview, isCreateTask, isOmt,
192	    isPortfolioProfile, isTaskProfile, isPxcProfile, hashQuery
193	  ]);
194	
195	  // Set during render, not in an effect: child effects (which start the data
196	  // loads) run before parent effects, so an effect here would file a profile's
197	  // first requests under the previous route and they'd never be aborted.
198	  // setActiveScope is idempotent and no-ops when the scope is unchanged.
199	  setActiveScope(scopeId);
