201	  /**
202	   * Returning to a profile whose load we cancelled: features stay mounted, so
203	   * its effects will not re-run by themselves and it would render empty
204	   * forever. Bumping the remount key gives it a clean mount and a fresh load.
205	   */
206	  const [reloadNonce, setReloadNonce] = React.useState({ portfolio: 0, task: 0, pxc: 0 });
207	  const isProfileRoute = isPortfolioProfile || isTaskProfile || isPxcProfile;
208	  React.useEffect(() => {
