252	          <ProjectOverviewFeature pageProps={pageProps} />
253	        </SuspensePage>
254	      </FeatureKeepAlive>
255	
256	      <FeatureKeepAlive active={isCreateTask} featureId="create-task" keepAlive={false}>
257	        <SuspensePage variant="create-task" label="Create Task">
258	          <CreateTaskFeature pageProps={pageProps} />
259	        </SuspensePage>
260	      </FeatureKeepAlive>
261	
262	      <FeatureKeepAlive active={isPortfolioProfile} featureId="portfolio-profile">
263	        <SuspensePage label="Portfolio Profile">
264	          <PortfolioProfileFeature
265	            pageProps={pageProps}
266	            remountKey={portfolioKey}
267	          />
268	        </SuspensePage>
269	      </FeatureKeepAlive>
270	
271	      <FeatureKeepAlive active={isTaskProfile} featureId="task-profile">
272	        <SuspensePage label="Task Profile">
273	          <TaskProfileFeature
274	            pageProps={pageProps}
275	            remountKey={taskKey}
276	          />
277	        </SuspensePage>
278	      </FeatureKeepAlive>
279	
280	      <FeatureKeepAlive active={isPxcProfile} featureId="pxc-profile">
281	        <SuspensePage label="PXC Profile">
282	          <PxcProfileFeature
283	            pageProps={pageProps}
284	            remountKey={pxcKey}
285	          />
286	        </SuspensePage>
