import * as React from 'react';
import StaticDashboardComponent from '../../pages/staticDashboard/components/StaticDashboardComponent';
import type { ISpaFeatureProps } from '../../shared/spa/types';

export default function StaticDashboardFeature(props: ISpaFeatureProps): React.ReactElement {
  const rawSiteUrl = String(
    props.pageProps?.siteUrl ||
    props.pageProps?.Context?.pageContext?.web?.absoluteUrl ||
    ''
  ).replace(/\/+$/, '');
  const normalizedSiteUrl = /\/sp$/i.test(rawSiteUrl)
    ? rawSiteUrl
    : (rawSiteUrl ? `${rawSiteUrl}/SP` : rawSiteUrl);

  return <StaticDashboardComponent props={{ ...props.pageProps, siteUrl: normalizedSiteUrl }} />;
}

