        setIsSetWorkingTodayTaskPopup(true);
    }

    const renderTaskDetailsOnHover = () => {
        setSelectedDirectFilterQuery((prev: any) => [...prev, "Task"]);
        resultType.current = ["Task"];
    }
    const handleDragStart = (e: any, result: any, Type: any) => {
        const dragData = { result: result, type: Type };
        e.dataTransfer.setData('OOTB_OMT', JSON.stringify(dragData));
    }
    return (
        <div className="w-full min-w-0 bg-white flex flex-col px-4 pt-3 pb-6 min-h-screen">
            {/* Top Accordion (Sites) */}
            {SelectedProp?.hideSitesFilter !== true && (
                <div className="w-full mb-4">
                    <ResultTypeFilter useForOMTTool={true} activeSitesSelectedItems={activeSitesSelectedItems} setActiveSitesSelectedItems={setActiveSitesSelectedItems} activeSites={activeSites} ContextValue={ContextValue} sites={masterTasksSiteData?.filter((elem: any) => elem?.siteName == "SP" || elem?.siteName == "GMBH")} selectedSiteTitles={selectedSiteTitles} setSelectedSiteTitles={setSelectedSiteTitles} clearFilterToggle={clearFilterToggle} resultType={resultType} onFilterChange={setResultTypesQueryPrepare} resultTypeQueryPrepare={resultTypeQueryPrepare} allFileTypeRefiners={allFileTypeRefiners} resultTypeAllDoc={resultTypeAllDoc} setResultTypesAllDoc={setResultTypesAllDoc} />
                </div>
            )}

            {/* Main Content Area */}
            <main className="w-full">
                <div className="sticky top-0 z-40 bg-white pb-2">
                        <div className="flex justify-between items-center w-full mb-2">
                            <h2 className="text-xl font-bold text-[#2f5597]">HHHH SmartSearch</h2>
                            <div><a className="text-sm font-medium text-blue-600 hover:underline" href={`${spOotbResultPage()}`} data-interception="off" target="_blank">SP OOTB Search</a></div>
                        </div>
                        <div className="flex flex-wrap items-center gap-2 mb-3">
                            <span className="relative flex-1 min-w-[200px] max-w-md">
                                <input type="text" className="search-input w-full rounded-lg border border-slate-300 bg-white px-3.5 py-2 text-sm font-medium text-slate-800 placeholder-slate-400 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100 shadow-sm transition-all" disabled={loading} value={query} onKeyDown={(e) => {
                                    if (e.key === "Enter") {
                                        setCloseSuggestions(true);   // close instantly
                                        filterDataAfterSearch();     // run search
                                    }
                                }}
                                    onChange={(e) => {
                                        setQuery(e.target.value);
                                        queryString.current = e.target.value;
                                        setCloseSuggestions(false);      // allow suggestions to reopen while typing
                                    }}
                                    placeholder="Search all site items"
                                />

                                {query && (
                                    <span className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 cursor-pointer font-bold text-xs" onClick={() => clearSearch()} >✕</span>
                                )}
                            </span>
                            {closeSuggestions === false && <AutoSuggestInput
                                spfxContext={spfxContext}
                                query={query}
                                setQuery={setQuery}
                                onSuggestionSelect={(title) => runSearchExact(title)}
                                closeSuggestions={closeSuggestions}
                            />}

                            <select className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm font-medium text-slate-700 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100 shadow-sm cursor-pointer transition-all" value={mode} onChange={(e) => setMode(e.target.value as Mode)} disabled={loading}>
                                <option value="exact">Exact phrase</option>
                                <option value="all">All words</option>
                                <option value="any">Any word</option>
                            </select>
                            <button type="button" className="flex items-center justify-center gap-2 rounded-md bg-[#2f5597] px-4 py-2 text-sm font-medium text-white hover:bg-[#244273] shadow-sm transition-all disabled:opacity-50" onClick={() => { setCloseSuggestions(true); filterDataAfterSearch(); }} disabled={query.trim() === "" || loading}>
                                <FaSearch style={{ color: "white" }} />
                                Search
                            </button>
                            {(loading || !loaded) && (
                                <span
                                    className="inline-block h-3.5 w-3.5 shrink-0 animate-spin rounded-full border-2 border-[#2f5596] border-r-transparent"
                                    role="status"
                                    aria-label={loading ? "Searching" : "Loading"}
                                />
                            )}
                            <a className="text-sm font-medium text-[#2f5597] hover:underline cursor-pointer" onClick={advanceSearchQuery}>Advanced Search</a>
                        </div>
                        <div className="flex justify-between items-center mb-1 gap-5 relative mt-4">
                            <div className="flex items-center gap-2">
                                <InfoToolTip
                                    content={{
                                        children: (
                                            <div className="p-2.5 max-w-[280px] leading-relaxed text-xs bg-white text-slate-700 rounded-lg border border-slate-200/80 shadow-xl">
                                                Displays the total number of search results matching the query and filters across selected sites.
                                            </div>
                                        ),
                                        className: "TodayTimeEntryToolTip"
                                    }}
                                    relationship="label"
                                    positioning="above"
                                >
                                    <span className="flex items-center gap-1.5 cursor-pointer text-sm font-medium text-slate-500 hover:text-slate-700 whitespace-nowrap">
                                        <Info16Regular className="text-[#2f5597] w-4 h-4 shrink-0" />
                                        About results
                                    </span>
                                </InfoToolTip>
                            </div>
                            <div className="flex items-center gap-6">
                                <InfoToolTip
                                    content={{
                                        children: (
