                                                        {result?.listData?.TaskPriority == 'Low' && <i className="text-green-500 mr-0.5 ms-Icon ms-Icon--SortDown" title='Low' aria-hidden="true"></i>}
                                                        {result?.listData?.TaskPriority == 'High' && <span title='High' className='text-red-500 font-bold mr-0.5'>!</span>}
                                                        {`(${result?.listData?.PriorityRank})`}
                                                    </span>
                                                </span>
                                                <span className="flex items-center gap-1.5 whitespace-nowrap">SmartTime:
                                                    <b className="font-semibold text-slate-800">{toHoursAndMinutes(result?.listData?.TotalTime)}</b>
