                                                        <span className="svg__iconbox svg__icon--clock w-3.5 h-3.5 inline-block"></span>
                                                    </a>
                                                </span>
                                            </div>
                                        )}
                                    </div>
                                </div>
                                );
                            })
                        ) : null}
                    </div>
                    {
                        currentResultsObj?.TotalRows > 50 && <CustomPagination
                            currentPage={currentPage}
                            totalPages={totalPages}
                            currentResultsCount={currentResultsCount}
                            onPageChange={onPageChange}
                        />
                    }
                </main>
            <Toaster />
            {showDialog === true && <ShareDialogPopup dialogItems={dialogItems} onClose={handleShareDailog} isOpen={showDialog} />}
