                <>
                    <style>{`
                        .centered-time-entry-panel {
                            position: fixed !important;
                            top: 0 !important;
                            left: 0 !important;
                            right: 0 !important;
                            bottom: 0 !important;
                        }
                        .centered-time-entry-panel .ms-Panel-contentInner {
                            position: relative !important;
                        }
                        .centered-time-entry-panel .ms-Panel-commands {
                            position: absolute !important;
                            top: 12px !important;
                            right: 8px !important;
                            z-index: 2 !important;
                            margin: 0 !important;
                            padding: 0 !important;
                        }
                        .centered-time-entry-panel .ms-Panel-navigation {
                            justify-content: flex-end !important;
                            align-items: center !important;
                            height: 32px !important;
                        }
                        .centered-time-entry-panel .ms-Panel-closeButton {
                            width: 32px !important;
                            height: 32px !important;
                            margin: 0 !important;
                            padding: 0 !important;
                        }
                        .centered-time-entry-panel .ms-Panel-header {
                            display: flex !important;
                            align-items: center !important;
                            width: 100% !important;
                            min-height: 56px !important;
                            margin: 0 !important;
                            padding: 12px 56px 12px 24px !important;
                            border-bottom: 1px solid #dddddd !important;
                        }
                        .centered-time-entry-panel .ms-Panel-main {
                            width: 650px !important;
