};
const CustomPagination: React.FC<{
    currentPage: number;
    totalPages: number;
    currentResultsCount: number; // Add this prop
    onPageChange: (page: number) => void;
}> = ({ currentPage, totalPages, currentResultsCount, onPageChange }) => {
    const renderPageNumbers = () => {
        const pages = [];
        const maxVisiblePages = 5;

        // Calculate effective total pages based on current results
        // If current page has less than 50 results, there shouldn't be more pages
        const effectiveTotalPages = currentResultsCount < 50 ? currentPage : totalPages;

        if (effectiveTotalPages <= maxVisiblePages) {
            for (let i = 1; i <= effectiveTotalPages; i++) {
                pages.push(
                    <button
                        key={i}
                        className={`pagination-btn ${currentPage === i ? 'active' : ''}`}
                        onClick={() => onPageChange(i)}
                    >
                        {i}
                    </button>
                );
            }
        } else {
            // Always show first page
            pages.push(
                <button
                    key={1}
                    className={`pagination-btn ${currentPage === 1 ? 'active' : ''}`}
                    onClick={() => onPageChange(1)}
                >
                    1
                </button>
            );

            if (currentPage > 3) {
                pages.push(<span key="ellipsis1" className="pagination-ellipsis">...</span>);
            }

            // Show pages around current page
            const start = Math.max(2, currentPage - 1);
            const end = Math.min(effectiveTotalPages - 1, currentPage + 1);

            for (let i = start; i <= end; i++) {
                pages.push(
                    <button
                        key={i}
                        className={`pagination-btn ${currentPage === i ? 'active' : ''}`}
                        onClick={() => onPageChange(i)}
                    >
                        {i}
                    </button>
                );
            }

            if (currentPage < effectiveTotalPages - 2) {
                // pages.push(<span key="ellipsis2" className="pagination-ellipsis">...</span>);
            }

            // Always show last page (only if it's different from first page)
            // if (effectiveTotalPages > 1) {
            //     pages.push(
            //         <button
            //             key={effectiveTotalPages}
            //             className={`pagination-btn ${currentPage === effectiveTotalPages ? 'active' : ''}`}
            //             onClick={() => onPageChange(effectiveTotalPages)}
            //         >
            //             {effectiveTotalPages}
            //         </button>
            //     );
            // }
        }

        return pages;
    };

    // Hide next button if current results are less than 50 OR if on last page
    const effectiveTotalPages = currentResultsCount < 50 ? currentPage : totalPages;
    const shouldShowNextButton = currentResultsCount >= 50 && currentPage < effectiveTotalPages;

    return (
        <div className="pagination">
            <button
                className="pagination-btn"
                onClick={() => onPageChange(currentPage - 1)}
                disabled={currentPage === 1}
            >
                <FaChevronLeft />
            </button>

            {renderPageNumbers()}

            {shouldShowNextButton && (
                <button
                    className="pagination-btn"
                    onClick={() => onPageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                >
                    <FaChevronRight />
                </button>
            )}
        </div>
    );
};
export default OOTBSearchOMT;

