    const [columnSettingConfigData, setColumnSettingConfigData] = React.useState<any>();
    const [isAWTLoaded, setIsAWTLoaded] = React.useState(false);
    const childRef = React.useRef<any>();
    // Mount nests the initial task band into AllProjectDataWithAWT and paints
    // that tree even while the AWT toggle is off. Call/subscribe used to key
    // off the toggle and swap back to PXC-only AllProject, which made children
    // vanish on title save. Track what is actually on screen.
    const showingNestedTasksRef = React.useRef(false);
    /** Nested PXC+AWT view active before Working Today / AWT By Team filter. */
    const nestedBeforeFilterRef = React.useRef(false);
    const paintOverviewTree = React.useCallback(() => {
        setFlatData(
            showingNestedTasksRef.current
                ? [...(AllProjectDataWithAWT || [])]
                : [...(AllProject || [])]
        );
    }, []);
    /** Restore flatData after leaving Working Today / AWT By Team — no refetch, no 90+AWT toggle change. */
    const restoreProjectsViewAfterFilter = React.useCallback(() => {
        showingNestedTasksRef.current =
            nestedBeforeFilterRef.current && !!(AllProjectDataWithAWT?.length);
        if (AllProjectDataWithAWT?.length) {
            setTaskTypeDataItem(countAwtFromTree(AllProjectDataWithAWT));
        }
        paintOverviewTree();
    }, [paintOverviewTree]);

