const groupedUsers = React.useMemo<ColumnDef<any, unknown>[]>(
    () => [
        {
            accessorKey: "",
            placeholder: "",
            hasCheckbox: true,
            hasCustomExpanded: true,
            hasExpanded: true,
            size: 55,
            id: 'Id',
        },
        {
            accessorKey: "TaskID",
            id: 'TaskID',
            placeholder: "ID",
            resetColumnFilters: false,
            filterFn: (row: any, columnName: any, filterValue: any) => {
                if (row?.original?.TaskID?.toLowerCase()?.includes(filterValue?.toLowerCase())) {
                    return true
                } else {
                    return false
                }
            },
            resetSorting: false,
            size: 80,
            cell: ({ row, getValue }) => (
                <div>
                    <>
                        <ReactPopperTooltipSingleLevel CMSToolId={row?.original?.TaskID} AllListId={AllListId} row={row?.original} singleLevel={true} masterTaskData={MyAllData} AllSitesTaskData={AllSitesAllTasks} />

                    </>
                </div>
            ),
        },
        {
            accessorFn: (row) => row?.siteType,
            cell: ({ row, getValue }) => (
                <>{
                    row?.original?.siteType !== "Master Tasks" ?
                        <span>
                            {row?.original?.SiteIcon != undefined ?
                                <img title={row?.original?.siteType} className="suffix_Usericon" src={row?.original?.SiteIcon} /> :
                                <div title={row?.original?.siteType} style={{ backgroundColor: `${row?.original?.PortfolioType?.Color || row?.original?.portfolioColor || 'var(--SiteColor,#2F5596)'}`, color: '#ffffff', width: '20px', height: '20px', lineHeight: '20px', borderRadius: '9999px', textAlign: 'center', fontSize: '11px', fontWeight: 600, display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }} className="Dyicons">{row?.original?.SiteIconTitle || row?.original?.siteType?.charAt(0) || "P"}</div>}
                        </span> : ''
                }</>
            ),
            id: "siteType",
            placeholder: "Site",
            resetColumnFilters: false,
            resetSorting: false,
            filterFn: (row: any, columnName: any, filterValue: any) => {
                if (row?.original?.siteType?.toLowerCase()?.includes(filterValue?.toLowerCase())) {
                    return true
                } else {
                    return false
                }
            },
            header: "",
            size: 60,
        },
        {
            accessorFn: (row) => row?.Title,
            cell: ({ row, column, getValue }) => (
                <div className='flex items-center'>
                    {row?.original?.type == 'Category' && row?.original?.Title != undefined ? row?.original?.Title : ''}
                    {row?.original?.Item_x0020_Type == "Task" || row?.original?.Item_x0020_Type == 'tasks' ?
                        <span>
                            <TaskProfileNavLink
                                taskRow={row?.original}
                                className='hreflink'
                                title={row?.original?.Title}
                                style={row?.original?.fontColorTask != undefined ? { color: `${row?.original?.fontColorTask}` } : { color: `${row?.original?.PortfolioItem?.PortfolioType?.Color}` }}
                            >
                                <HighlightableCell value={getValue()} searchTerm={column.getFilterValue() != undefined ? column.getFilterValue() : childRef?.current?.globalFilter} />
                            </TaskProfileNavLink>
                            {row?.original?.descriptionsSearch?.length > 0 ? <span className='alignIcon mt--5 '><InfoIconsToolTip Discription={row?.original?.bodys} row={row?.original} /></span> : ''}
                        </span> : ''}
                </div>

            ),
            id: "Title",
            placeholder: "Title",
            resetColumnFilters: false,
            resetSorting: false,
            header: "",
            size: 450,
        },
        {
            accessorFn: (row) => row?.ProjectTitle,
