const loadAllSiteTaskDataUncached = async (
    allListId?: any | null,
    filter?: any | null,
    pertiCularSites?: any | null,
    showOffShore?: any | undefined
) => {
    // 1. Optimize query - only select fields you actually need
    const query = `Id,Title,FeedBack,Comments,BasicImageInfo,TotalTime,PriorityRank,LocalPriority,WorkingAction,Remark,EstimatedTimeDescription,ClientActivityJson,ComponentLink,TaskID,OffshoreImageUrl,OffshoreComments,SiteCompositionSettings,Sitestagging,Priority,Status,ItemRank,IsTodaysTask,Body,PercentComplete,Categories,StartDate,DueDate,Created,Modified,TaskLevel,workingThisWeek,EstimatedTime,Project/Id,Project/Title,Project/PortfolioStructureID,Project/PriorityRank,ParentTask/Id,ParentTask/Title,ParentTask/TaskID,Editor/Id,Editor/Title,Portfolio/Id,Portfolio/Title,Portfolio/PortfolioStructureID,TaskType/Id,TaskType/Title,TaskType/Level,Author/Id,Author/Title,SmartDocument/Id,SmartDocument/Title,TaskCategories/Id,TaskCategories/Title,AssignedTo/Id,AssignedTo/Title,TeamMembers/Id,TeamMembers/Title,ResponsibleTeam/Id,ResponsibleTeam/Title,ClientCategory/Id,ClientCategory/Title&$expand=AssignedTo,Project,ParentTask,Editor,Author,Portfolio,SmartDocument,TaskType,TeamMembers,ResponsibleTeam,TaskCategories,ClientCategory${filter ? `&$filter=${filter}` : ''}`;

    try {
        // 2. Load site config once at the beginning
        const siteConfig = await loadSmartMetadata(allListId, "Sites");

        // 3. Optimize site filtering with early returns
        const filteredSiteConfig:any = getFilteredSiteConfig(siteConfig, pertiCularSites, showOffShore);

        if (!filteredSiteConfig?.length) {
            return [];
        }

        // Deduplicate by listId + site host so hubs that share the same task
        // list never issue a second GET for the same data in one call.
        const seenLists = new Set<string>();
        const uniqueSiteConfig = filteredSiteConfig.filter((site: any) => {
            const listId = site?.listId;
            if (!listId) return false;
            const rawUrl = site?.siteUrl?.Url || site?.siteUrl || allListId?.siteUrl || '';
            const siteUrl = resolveAbsoluteSiteUrl(rawUrl);
            const key = `${String(siteUrl || rawUrl).replace(/\/+$/, '').toLowerCase()}|${listId}`;
            if (seenLists.has(key)) return false;
            seenLists.add(key);
            return true;
        });

        // 4. Pre-calculate current date once
        const currentDate = moment(new Date()).format("DD/MM/YYYY");

        // 5. Batch API calls with concurrency limit to prevent overwhelming the server
        const BATCH_SIZE = 5; // Process 5 sites at a time
        const allTasks:any = [];

        for (let i = 0; i < uniqueSiteConfig.length; i += BATCH_SIZE) {
            const batch:any = uniqueSiteConfig.slice(i, i + BATCH_SIZE);
            const batchPromises:any = batch.map((site:any) => processSite(site, query, allListId, currentDate));

            // const batchResults = await Promise.all(batchPromises);

            // // Handle results and errors
            // batchResults.forEach((result:any, index:any) => {
            //     if (result.status === 'fulfilled' && result.value) {
            //         allTasks.push(...result.value);
            //     } else if (result.status === 'rejected') {
            //         console.error(`Error processing site ${batch[index]?.Title}:`, result.reason);
            //     }
            // });
            const batchResults = await Promise.all(batchPromises);

// all promises resolved, no need to check .status
            batchResults.forEach((tasks: any[]) => {
                if (tasks) {
                    allTasks.push(...tasks);
                }
            });
        }

        return allTasks;

    } catch (error) {
        devError(error, "Error in loadAllSiteTaskData");
        return [];
    }
};

// 6. Extract site filtering logic
function getFilteredSiteConfig(siteConfig: any[], pertiCularSites: any, showOffShore: boolean) {
    const excludedSites = new Set([
        "master tasks", "sdc sites", "small projects", 
        "migration", "gender", "drr", "health", "de"
    ]);

            {row?.original?.workingActionValue?.map((elem: any) => {
                const relevantTitles: any = ["Bottleneck", "Attention", "Phone", "Approval"];
                return relevantTitles?.includes(elem?.Title) && elem?.InformationData?.length > 0 && (
