async function processSite(site: any, query: string, allListId: any, currentDate: string) {
    try {
        const siteUrl = resolveAbsoluteSiteUrl(
            site?.siteUrl?.Url || site?.siteUrl,
            allListId?.siteUrl
        );
        if (!siteUrl || !site?.listId) {
            return [];
        }
        const web = new Web(siteUrl);

        // 8. Add timeout and better error handling
        const data = await Promise.race([
            web.lists.getById(site?.listId).items.select(query).getAll(),
            new Promise((_, reject) => 
                setTimeout(() => reject(new Error('Request timeout')), 150000)
            )
        ]);

        // 9. Optimize task processing
        return (data as any[])?.map(task => processTask(task, site, currentDate)) || [];

    } catch (error) {
        console.error(`Error fetching data for site ${site?.Title}:`, error);
        return [];
    }
}

// 10. Extract and optimize task processing
function processTask(task: any, site: any, currentDate: string) {
    // Basic properties
    task.siteType = site.Title || site.siteName;
    task.listId = site.listId;
    task.siteUrl = site.siteUrl?.Url || site.siteUrl;
    task.TaskTypeValue = '';
    task.projectPriorityOnHover = '';
    task.taskPriorityOnHover = task?.PriorityRank;
    task.SiteIcon = site?.Item_x005F_x0020_Cover?.Url;
    task.Item_x0020_Type = "Task";
    task.portfolioItemsSearch = site.Title || site.siteName;
    task.AssignedToIds = [];
    task.BackupAssignedTo = task?.AssignedTo ? [...task.AssignedTo] : [];
    task.IsTodaysTask = false;

    // Optimize time calculations
    if (typeof task?.TotalTime === 'number') {
        task.TotalTaskTime = (task.TotalTime / 60).toFixed(2);
    }

    // Optimize percentage calculation
    if (task.PercentComplete !== undefined) {
        task.PercentComplete = Math.round(task.PercentComplete * 100);
    }

    // Optimize date processing
    if (task?.DueDate) {
        const dueDate = new Date(task.DueDate);
        task.serverDueDate = dueDate.setHours(0, 0, 0, 0);
        task.DisplayDueDate = moment(dueDate).format("DD/MM/YYYY");
    } else {
        task.DisplayDueDate = '';
    }

    task.DisplayCreateDate = moment(task.Created).format("DD/MM/YYYY");

    // Portfolio processing
    if (task?.Portfolio?.Id) {
        task.portfolio = task.Portfolio;
        task.PortfolioTitle = task.Portfolio.Title;
        task.PortfolioId = task.Portfolio.Id;
    }

    // Project processing
    if (task.Project) {
        task.ProjectTitle = task.Project.Title;
        task.ProjectId = task.Project.Id;
        task.projectStructerId = task.Project.PortfolioStructureID;

        const joinedData = [];
        if (task.Project.Title) joinedData.push(`Title: ${task.Project.Title}`);

